// 亲生控制页只读本人会面和参与许可，关系真值并不直接成为所有人物的公开族谱。
#include "biological_control_commands.hpp"
#include "resident/views/common_presentation.hpp"
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
V identity(const CommonStore& c){using namespace boundary;StableId world;const char* digits="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=digits[b>>4];world+=digits[b&15];}const auto& i=c.state().identity;return obj({{"world_id",V{world}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
V person(const BiologicalControlDecisionContext& x,const StableId& actor){using namespace boundary;auto name=CommonPresentation(x.people.common.state(),x.people.catalog).display_name(actor);auto age=x.people.births?read_actor_age(x.people.common,x.people.catalog,*x.people.births,actor):read_actor_age(x.people.common,x.people.catalog,actor);return obj({{"actor_id",V{actor}},{"name",V{name.ok?name.value:actor}},{"age_years",V{age.ok?age.value.age_years:Integer{-1}}}});}
}
Outcome<BoundaryValue> query_biological_control_page(const BiologicalControlDecisionContext& x,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& death_read,const InteractionState& interactions,const InteractionAccess& access,const FamilyLegacyState& legacy,const FamilyLegacyPlayableRead& playable,Integer page,const DiscipleControlRelationContext* disciple,const CollateralControlDecisionContext* collateral){
 using namespace boundary;if(page<0||page>255)return {false,{},common_failure("InvalidLegacyPage").error};const auto& c=x.people.common;auto valid=validate_family_legacy(c,family,deaths,death_read,x.people.catalog,x.interaction_catalog,x.original_requests,legacy,playable,disciple,&x,collateral);if(!valid.ok)return {false,{},valid.error};const auto& actor=c.state().metadata.player_actor_id;const auto* current=c.actor(actor);if(!current)return {false,{},common_failure("UnknownActor",actor).error};V::Array requests,consents;
 auto operation=[&](const BiologicalControlCommand& cmd){auto quoted=preview_biological_control_command(x,family,deaths,death_read,interactions,access,legacy,playable,actor,cmd,disciple,collateral);V::Dict params{{"request_id",V{cmd.request_id}}};if(!cmd.successor_actor_id.empty())params.emplace_back("successor_actor_id",V{cmd.successor_actor_id});if(!cmd.consent_fact_id.empty())params.emplace_back("consent_fact_id",V{cmd.consent_fact_id});return obj({{"command",V{cmd.kind}},{"params",V{std::move(params)}},{"available",V{quoted.ok}},{"code",V{quoted.ok?StableId{}:quoted.error.original.code}}});};
 // 只有当前本人参与且provider真实say的会面可展示新许可；实际Born模板读继续逐opening检验。
 std::set<std::pair<StableId,StableId>> offered;
 if(current->alive)for(const auto& session:interactions.interactions){if(session.actor_id!=actor||session.phase!="say")continue;const auto& child=session.context.provider_actor_id;if(child.empty())continue;for(const auto& row:x.catalog.definitions.rows()){const auto& d=row.second;if(d.meeting_kind==BiologicalControlMeetingKind::installed_candidate&&(d.predecessor_actor_id!=actor||d.successor_actor_id!=child))continue;auto proof=preview_biological_control_decision(x,interactions,access,actor,child,d.id,"accept");if(!proof.ok||!offered.emplace(d.id,child).second)continue;requests.push_back(obj({{"request_id",V{d.id}},{"successor",person(x,child)},{"relation_basis",V{StableId{"biological"}}},{"action",operation({"family_biological_accept",d.id,child,{}})}}));}}
 for(const auto& row:legacy.consents.rows()){const auto& source=row.second.source;if(!source.biological_origin||(source.predecessor_actor_id!=actor&&source.successor_actor_id!=actor))continue;StableId status="accepted";for(const auto& r:legacy.revocations.rows())if(r.second.consent_fact_id==row.first)status="revoked";for(const auto& a:legacy.activations.rows())if(a.second.consent_fact_id==row.first)status="activated";V::Array operations;
  if(status=="accepted"&&source.predecessor_actor_id==actor){if(!current->alive){auto quote=preview_family_legacy_activation(c,family,deaths,death_read,x.people.catalog,x.interaction_catalog,x.original_requests,legacy,playable,row.first,disciple,&x,collateral);operations.push_back(obj({{"command",V{StableId{"family_legacy_activate"}}},{"params",obj({{"consent_fact_id",V{row.first}}})},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}}));}else{auto proof=preview_biological_control_decision(x,interactions,access,actor,source.successor_actor_id,source.request_id,"revoke");if(proof.ok)operations.push_back(operation({"family_biological_revoke",source.request_id,{},row.first}));}}
  consents.push_back(obj({{"consent_fact_id",V{row.first}},{"status",V{status}},{"accepted_tick",V{source.tick}},{"successor",person(x,source.successor_actor_id)},{"relation_basis",V{StableId{"biological"}}},{"actions",V{std::move(operations)}}}));
 }
 const Integer request_count=requests.size(),consent_count=consents.size();auto slice=[page](V::Array& items){V::Array out;for(Integer i=page*16;i<std::min<Integer>(items.size(),page*16+16);++i)out.push_back(std::move(items[static_cast<std::size_t>(i)]));items=std::move(out);};slice(requests);slice(consents);
 return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"page",V{page}},{"request_count",V{request_count}},{"consent_count",V{consent_count}},{"requests",V{std::move(requests)}},{"consents",V{std::move(consents)}},{"relation_basis",V{StableId{"biological"}}},{"awaiting_control_choice",V{!current->alive}},{"scope",V{StableId{"own_life_control_only"}}},{"assets_transferred",V{false}},{"knowledge_granted",V{false}},{"public_authority_transferred",V{false}}}),{}};
}
}
